update pages set contenu = '{"gabarit":"fiche","chapeau":"AMAZON exploite le centre logistique ORY4 en continu, 24 heures sur 24. Depuis septembre 2022, Migen y assure les interventions préventives une semaine sur deux, sous contrat annuel.","fiche":[],"contexte":"**Un site qui ne ferme jamais n''a pas de fenêtre de maintenance.** Chaque minute d''immobilisation se paie sur les flux sortants.\nLa contrainte posée par AMAZON tenait en quatre points :\n**Aucune plage longue** : Les opérations doivent tenir dans quelques heures.\n**Un volume d''équipements élevé** : Beaucoup de machines à couvrir sur le même créneau.\n**Un rythme imposé** : Une semaine sur deux, sans décalage possible.\n**Un risque qui remonte vite** : Le préventif en retard se transforme en défaillance.","intervention":"**Effectif massé sur le créneau** : 10 à 20 techniciens polyvalents mobilisés en même temps, pour traiter un grand nombre d''interventions préventives en parallèle.\n**Format calé sur 8 heures** : Les opérations sont découpées pour entrer dans des plages de quelques heures, sans débordement sur l''exploitation.\n**Préparation partagée** : Les équipes AMAZON organisent les opérations en amont et rendent les pièces de rechange disponibles avant l''arrivée des techniciens.\n**Exécution et contrôle** : Migen prend en charge l''exécution, le contrôle et les tests en série de chaque opération.\n**Rythme tenu dans la durée** : Le dispositif tourne une semaine sur deux depuis 2022, sans rupture.","resultats":[]}'::jsonb where path = '/preuves/amazon-centre-logistique/';
update pages set contenu = jsonb_set(contenu, '{fiche}', (contenu->'fiche') || '[{"libelle":"Client","valeur":"AMAZON"},{"libelle":"Site","valeur":"Centre logistique ORY4"},{"libelle":"Période","valeur":"Depuis septembre 2022, mission en cours"},{"libelle":"Effectif Migen","valeur":"10 à 20 techniciens polyvalents"},{"libelle":"Durée d''intervention","valeur":"8 heures"},{"libelle":"Fréquence","valeur":"1 semaine sur 2"},{"libelle":"Nature des travaux","valeur":"Maintenance préventive, contrôle, tests en série"},{"libelle":"Cadre","valeur":"Contrat annuel"}]'::jsonb) where path = '/preuves/amazon-centre-logistique/';
update pages set contenu = jsonb_set(contenu, '{resultats}', (contenu->'resultats') || '[{"valeur":"Une opération maîtrisée","libelle":"Délicate au départ, elle l''est devenue grâce à l''organisation et à l''entraînement des équipes, côté prestataire comme côté client."},{"valeur":"Un risque de défaillance réduit","libelle":"Le préventif passe dans la fenêtre prévue, ce qui sécurise la continuité opérationnelle du site."},{"valeur":"Un périmètre qui s''élargit","libelle":"Migen réalise toujours ces interventions, avec des responsabilités de plus en plus importantes."}]'::jsonb) where path = '/preuves/amazon-centre-logistique/';
